insert into imhcc.site_settings (id, company_name, tagline, hero_title, hero_subtitle, phone_primary, phone_secondary, email, address, business_hours, facebook_url, messenger_url, map_embed_url, latitude, longitude, about_intro, mission, vision, stats) values (1, 'Iloilo Modern Homes Construction Co.', 'Live in the very best home where your family can nurture and grow in safety. Construct with us!', 'We design. We execute.', 'Your dream home starts here. From house construction to condo renovations, modular kitchens, and PVC ceilings, Iloilo Modern Homes brings your vision to life with quality workmanship, affordable rates, and on-time completion.', '0917 384 3099', '0966 396 3855', null, 'Santa Barbara, Iloilo, Philippines', 'Monday to Saturday, 8:00 AM to 5:00 PM', 'https://www.facebook.com/modernhomesrose', 'https://m.me/modernhomesrose?ref=website', null, 10.768184, 122.508359, 'Iloilo Modern Homes Construction Co. is a construction, renovation, and hardware supply business based in Santa Barbara, Iloilo. We serve homeowners and businesses across Iloilo City and Iloilo Province, from new builds to kitchen makeovers and complete interior fit-outs.', 'To build safe, beautiful, and lasting spaces for Ilonggo families and businesses through honest pricing, skilled workmanship, and clear communication from first visit to handover.', 'To be the most trusted construction partner in Iloilo, known for modern design, quality results, and customers who recommend us to their families.', '[{"value":"Free","label":"Site visit and quotation"},{"value":"Iloilo-wide","label":"City and province coverage"},{"value":"One team","label":"Design, build, and supply"},{"value":"Real work","label":"Every photo is our own project"}]'::jsonb) on conflict (id) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('modular-kitchens-cabinets', 'Modular kitchens and cabinets', 'Interior', 'Custom cabinets, islands, and countertops built to fit your space.', 'We design and install modular kitchen cabinets, breakfast islands, pantry units, and countertops in laminate, solid surface, or marble finishes. Every unit is measured on site so it fits your space and your daily routine.', array['Base and wall cabinets', 'Kitchen islands and peninsulas', 'Countertops and backsplash', 'Under-cabinet and pendant lighting']::text[], '/images/projects/kitchen-island-pendants.jpg', 1, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('interior-fit-outs', 'Interior fit-outs', 'Interior', 'TV feature walls, built-ins, wall panels, and finishing works.', 'Turn a bare unit or room into a finished, livable space. We build TV feature walls, wardrobes, study desks, wall cladding, and room partitions for homes, condos, and offices.', array['TV and feature walls', 'Wardrobes and built-ins', 'Fluted and PVC wall panels', 'Condo and office fit-outs']::text[], '/images/projects/tv-wall-aurora.jpg', 2, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('ceilings-and-lighting', 'PVC ceilings and lighting', 'Interior', 'PVC, gypsum, and wood ceilings with cove and accent lighting. Clean finish, on time.', 'PVC ceiling installation, drop ceilings, cove lighting, wood slat ceilings, and lighting layouts that make a room feel finished. Quality workmanship, affordable rates, a clean finish, and on-time completion. We handle framing, boarding, finishing, and the electrical work behind it.', array['PVC ceiling installation', 'Gypsum board drop ceilings', 'Cove and LED strip lighting', 'Wood slat ceilings', 'Lighting layout and installation']::text[], '/images/projects/bedroom-cove-ceiling.jpg', 3, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('bathroom-renovation', 'Bathroom renovation', 'Renovation', 'Tiling, fixtures, plumbing, and complete bathroom makeovers.', 'From a simple fixture upgrade to a full marble bathroom, we handle demolition, waterproofing, plumbing, tiling, vanities, and lighting.', array['Waterproofing and tiling', 'Vanities and mirrors', 'Plumbing and fixtures', 'Shower and tub installation']::text[], '/images/projects/bathroom-round-mirror.jpg', 4, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('residential-construction', 'House design and build', 'Construction', 'We design. We execute. New houses from plans to turnover.', 'We design your house and build it, from the first floor plan and 3D concept to foundation, structure, roofing, and finishing. One team coordinates the plans, permits, and every trade, so you deal with one contractor from start to turnover.', array['House design and 3D concepts', 'Foundation and structural works', 'Masonry and concrete', 'Roofing', 'Finishing and turnover']::text[], '/images/projects/loft-bedroom.jpg', 5, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('commercial-construction', 'Commercial fit-out', 'Construction', 'Counters, cafés, offices, and shops built for business.', 'Fit-out and construction of cafés, reception and service counters, offices, shops, and rental spaces: wood-slat cladding, feature walls, track lighting, and backlit signage, planned to minimize downtime for your business.', array['Café and reception counters', 'Office and store fit-outs', 'Feature walls and signage', 'Rental unit construction']::text[], '/images/projects/studio-pendant-lights.jpg', 6, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('renovation', 'Home and condo renovation', 'Renovation', 'Don''t replace your home, transform it. From outdated to outstanding.', 'Whole-house, condo, or room-by-room renovation: layout changes, repairs, feature walls, ceilings, built-ins, and modern finishes that turn an outdated space into one you love coming home to.', array['Condo unit makeovers', 'Layout changes', 'Repairs and restoration', 'Modern finishes']::text[], '/images/projects/white-kitchen-wood-ceiling.jpg', 7, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('electrical-and-plumbing', 'Electrical and plumbing', 'Technical', 'Safe wiring, lighting, water lines, and drainage.', 'Electrical wiring, panel upgrades, lighting, water supply lines, and drainage, done to code by experienced workers.', array['Wiring and panel upgrades', 'Lighting installation', 'Water lines and drainage']::text[], '/images/projects/kitchen-teal-cove.jpg', 8, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('roofing-flooring-painting', 'Roofing, flooring, and painting', 'Finishing', 'Roof installation, tiles and vinyl, and interior and exterior paint.', 'Roof installation and repair, floor tiling and vinyl planks, and interior and exterior painting.', array['Roofing installation and repair', 'Floor tiles and vinyl planks', 'Interior and exterior painting']::text[], '/images/projects/charcoal-kitchen-island.jpg', 9, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('phased-kitchen-renovation', 'Phased kitchen renovation', 'Renovation', 'Your dream kitchen, one phase at a time, according to your budget and priorities.', 'Not ready to redo the whole kitchen at once? We plan the full design up front, then build it in phases: cabinets first, then the countertop and backsplash, then the ceiling and lighting, or in whatever order fits your budget and priorities. Every phase is finished properly, so the kitchen looks complete at each step.', array['Full kitchen design up front', 'Phase-by-phase quotation', 'Modular cabinets', 'Countertops, backsplash, ceiling, and lighting']::text[], '/images/projects/white-kitchen-marble-counter.jpg', 10, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('building-permit-assistance', 'Building permit assistance', 'Construction', 'We guide you through every permit step so nothing is missed.', 'Building a house in the Philippines takes paperwork: land title, signed plans, barangay clearance, the building permit, and fees. We walk you through each step under the National Building Code and prepare the plans your application needs. See the full checklist on our Resources page.', array['Land title check', 'Signed and sealed building plans', 'Barangay clearance', 'Building permit application', 'Permit fees and bond']::text[], '/images/projects/loft-bedroom.jpg', 11, false, true) on conflict (slug) do nothing;
